+
+}
+
+template<class T>
+bool gsBiCgStab<T>::step( typename gsBiCgStab<T>::VectorType& x )
+{
+    T rho_old = m_rho;
+    m_rho = m_r0.col(0).dot(m_res.col(0));
+
+    if (math::abs(m_rho) < m_restartThereshold * m_r0.col(0).dot(m_r0.col(0)) )
+    {
