         if( refEltsFirst.size() > 0 )
             m_bases[ bi.first().patch ]->refineElements( refEltsFirst );
         if( refEltsSecond.size() > 0 )
             m_bases[ bi.second().patch ]->refineElements( refEltsSecond );

